  // a layer change animates even while paused; the loop stops itself once everything has settled
  sEffect(() => {
    if (!playing) settle.current(); // never leave a paused replay half-faded
    redraw.current();
    kick();
  }, [playing, mode]);

  const seek = (e) => {
