168	  const P = (p) => [W / 2 + (p.x - cam[0]) * sc, plotH / 2 + (p.y - cam[1]) * sc];
169	  const font = (px, w = 500) => `${w} ${px * dpr}px "JetBrains Mono", ui-monospace, monospace`;
170	  const poses = S.tracks.map((tr) => (pose ? mixPose(poseAt(tr, pose.fromT), tr[S.pose], pose.u) : poseAt(tr, t)));
171	  const locked = pose ? Math.min(17, Math.floor(pose.lock * 17 + 1e-6)) : 17; // joints revealed so far, in COCO order (head to ankles)
172	
173	  poses.forEach((ps, c) => {
174	    const kp = ps.kp;
175	    const col = tone(c, colour);
176	    // tracking box, as corner brackets
177	    const [bx1, by1] = P({ x: ps.box[0], y: ps.box[1] });
178	    const [bx2, by2] = P({ x: ps.box[2], y: ps.box[3] });
179	    const x1 = Math.max(2 * dpr, bx1), y1 = Math.max(18 * dpr, by1), x2 = Math.min(W - 2 * dpr, bx2), y2 = Math.min(plotH - 4 * dpr, by2);
180	    ctx.lineWidth = 1.5 * dpr; ctx.strokeStyle = tone(c, colour, lerp(0.62, 0.75, colour));
181	    bracket(ctx, x1, y1, x2, y2, Math.min(x2 - x1, y2 - y1) * 0.12);
182	    ctx.font = font(11); ctx.fillStyle = col; ctx.textBaseline = 'bottom';
183	    ctx.fillText((colour > 0.5 ? CORNER_NAME[c].toUpperCase() : 'PERSON') + '  ' + (ps.conf / 100).toFixed(2), x1, y1 - 5 * dpr);
184	
185	    // bones; while a pose is locking on, a bone turns solid once both of its joints are found
186	    ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.lineWidth = 2.4 * dpr;
187	    const solid = new Path2D(), ghost = new Path2D();
188	    BONES.forEach(([u, v]) => {
189	      if (kp[u].c < MIN_CONF || kp[v].c < MIN_CONF) return;
190	      const p = P(kp[u]), q = P(kp[v]);
191	      const path = u < locked && v < locked ? solid : ghost;
