214	        if (age < RING) {
215	          ctx.lineWidth = 1.2 * dpr; ctx.strokeStyle = `rgba(${INK_RGB.join(',')},${(1 - age / RING) * 0.9})`;
216	          ctx.beginPath(); ctx.arc(x, y, (4 + age * 6) * dpr, 0, Math.PI * 2); ctx.stroke();
217	        }
218	      } else if (j >= 5 && p.c >= MIN_CONF) {
219	        ctx.fillStyle = '#0f1012'; ctx.beginPath(); ctx.arc(x, y, 2.6 * dpr, 0, Math.PI * 2); ctx.fill();
220	        ctx.lineWidth = 1.4 * dpr; ctx.strokeStyle = col; ctx.stroke();
221	      }
222	    });
223	  });
224	
225	  // strikes: flash the limb that threw it and ring the target
226	  let callout = null;
227	  if (strikes) {
228	    S.events.forEach((e) => {
229	      const ph = t - e.si;
230	      if (ph < -3 || ph > 14) return;
231	      const k = ph < 0 ? (ph + 3) / 3 : 1 - ph / 14;
232	      const kp = poses[e.c].kp;
233	      const pts = e.chain.map((j) => kp[j]).filter((p) => p.c >= MIN_CONF).map(P);
234	      if (pts.length < 2) return;
235	      ctx.globalAlpha = k; ctx.strokeStyle = CORNER[e.c]; ctx.lineWidth = 6 * dpr;
236	      ctx.beginPath(); pts.forEach((p, i) => (i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]))); ctx.stroke();
237	      const end = pts[pts.length - 1];
238	      ctx.lineWidth = 1.6 * dpr;
239	      ctx.beginPath(); ctx.arc(end[0], end[1], (9 + 10 * (1 - k)) * dpr, 0, Math.PI * 2); ctx.stroke();
240	      ctx.font = font(11, 600); ctx.fillStyle = CORNER[e.c]; ctx.textBaseline = 'middle';
241	      ctx.fillText((STRIKE_LABEL[e.a] || e.a).toUpperCase(), end[0] + 16 * dpr, end[1] - 14 * dpr);
242	      ctx.globalAlpha = 1;
243	      if (Math.abs(ph) <= WINDOW) callout = e;
244	    });
245	  }
246	
247	  // 1.2 s trail of the striking hand or foot, as the strike model reads it
248	  if (mode === 'strike' && !pose) {
249	    const e = S.events.reduce((best, ev) => (Math.abs(t - ev.si) < Math.abs(t - (best ? best.si : Infinity)) ? ev : best), null);
250	    if (e && Math.abs(t - e.si) <= WINDOW) {
251	      const j = e.chain[e.chain.length - 1];
252	      const from = Math.max(0, Math.ceil(e.si - WINDOW)), to = Math.min(t, e.si + WINDOW);
253	      ctx.lineWidth = 1.5 * dpr;
254	      for (let i = from; i < to; i++) {
255	        const p = S.tracks[e.c][i].kp[j], q = S.tracks[e.c][Math.min(S.n - 1, i + 1)].kp[j];
256	        if (p.c < MIN_CONF || q.c < MIN_CONF) continue;
257	        const u = P(p), v = P(q);
258	        ctx.strokeStyle = CORNER[e.c]; ctx.globalAlpha = 0.25 + 0.6 * ((i - from) / (2 * WINDOW));
259	        ctx.beginPath(); ctx.moveTo(u[0], u[1]); ctx.lineTo(v[0], v[1]); ctx.stroke();
260	        ctx.beginPath(); ctx.arc(u[0], u[1], 1.8 * dpr, 0, Math.PI * 2); ctx.fillStyle = CORNER[e.c]; ctx.fill();
261	      }
262	      ctx.globalAlpha = 1;
263	    }
264	  }
265	
266	  // sample strip: one tick per pose sample, playhead, strike marks, model window (hidden on the pose and corner layers)
267	  if (strip > 0.01) {
268	    ctx.globalAlpha = strip;
269	    const xL = 14 * dpr, xR = W - 14 * dpr, base = H - 12 * dpr;
270	    const X = (s) => xL + (s / (S.n - 1)) * (xR - xL);
271	    ctx.fillStyle = `rgba(${INK_RGB.join(',')},.16)`;
272	    for (let i = 0; i < S.n; i++) ctx.fillRect(X(i), base - (i % HZ === 0 ? 9 : 4) * dpr, 1 * dpr, (i % HZ === 0 ? 9 : 4) * dpr);
273	    if (mode === 'strike') {
274	      const w0 = X(Math.max(0, t - WINDOW)), w1 = X(Math.min(S.n - 1, t + WINDOW));
275	      ctx.fillStyle = `rgba(${INK_RGB.join(',')},.09)`; ctx.fillRect(w0, base - 16 * dpr, w1 - w0, 16 * dpr);
276	      ctx.font = font(10.5); ctx.fillStyle = `rgba(${INK_RGB.join(',')},.7)`; ctx.textBaseline = 'bottom';
277	      ctx.fillText('1.2 s WINDOW  31 POSES', Math.min(w0, xR - 150 * dpr), base - 20 * dpr);
278	    }
279	    if (strikes) S.events.forEach((e) => { ctx.fillStyle = CORNER[e.c]; ctx.fillRect(X(e.si) - 2.5 * dpr, base - 14 * dpr, 5 * dpr, 5 * dpr); });
280	    ctx.fillStyle = `rgb(${INK_RGB.join(',')})`; ctx.fillRect(X(t) - 0.75 * dpr, base - 18 * dpr, 1.5 * dpr, 18 * dpr);
281	    ctx.globalAlpha = 1;
282	  }
283	  return { callout, locked };
284	}
285	
286	/* ---------- component ---------- */
287	const reducedMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;
288	const colourFor = (mode) => (mode === 'detect' ? 0 : 1);
289	const stripFor = (mode) => (mode === 'detect' || mode === 'corners' ? 0 : 1);
290	const zoomFor = (mode) => (mode === 'detect' ? 1 + POSE_ZOOM : 1);
291	
292	function ExchangeStage({ mode }) {
293	  const S = sRef(null);
294	  if (!S.current) S.current = prepExchange(window.EXCHANGE);
