296	  const modeRef = sRef(mode);
297	  const tRef = sRef(LOOP_START);
298	  const [playing, setPlaying] = sState(() => !reducedMotion());
299	  const playingRef = sRef(playing);
300	  const [passed, setPassed] = sState(0);
301	  const passedRef = sRef(0);
302	  const redraw = sRef(() => {});
303	  // restart = hold on the last frame, fade out, jump back while invisible, fade in already playing
304	  const loop = sRef({ phase: 'play', time: 0 });
305	  const settle = sRef(() => {});
306	  const kick = () => wrapRef.current.dispatchEvent(new Event('stage:play'));
307	
308	  modeRef.current = mode;
309	  playingRef.current = playing;
310	
311	  sEffect(() => {
312	    const s = S.current, cv = canvasRef.current, ctx = cv.getContext('2d');
313	    let W = 0, H = 0, dpr = 1, raf = 0, last = 0, visible = true;
314	    let lastMode = null, pose = null; // pose: { fromT, u, lock } while the detect layer holds a frame
315	    const vis = { colour: colourFor(modeRef.current), strip: stripFor(modeRef.current), zoom: zoomFor(modeRef.current) };
316	    if (!playingRef.current) tRef.current = s.events[2].si + 2;
317	
318	    const setFade = (v) => wrapRef.current.style.setProperty('--fade', v.toFixed(3));
319	    const smooth = (x) => x * x * (3 - 2 * x);
320	    const paint = () => {
321	      const view = { t: tRef.current, mode: modeRef.current, colour: vis.colour, strip: vis.strip, zoom: vis.zoom, pose: pose && { fromT: pose.fromT, u: easeInOut(pose.u), lock: pose.lock } };
