380	      } else {
381	        tRef.current = Math.min(s.n - 1, tRef.current + dt * HZ * (modeRef.current === 'strike' ? 0.45 : 1));
382	        if (L.phase === 'in') {
383	          L.time += dt;
384	          setFade(smooth(Math.min(1, L.time / LOOP_FADE)));
385	          if (L.time >= LOOP_FADE) { L.phase = 'play'; setFade(1); }
386	        }
387	      }
388	    };
389	    const tick = (now) => {
390	      raf = 0;
391	      if (!visible) { last = 0; return; }
392	      const dt = last ? Math.min(0.1, (now - last) / 1000) : 0; last = now;
393	      if (modeRef.current !== lastMode) { enterMode(lastMode, modeRef.current); lastMode = modeRef.current; }
394	      const busy = stepVisuals(dt);
395	      if (playingRef.current && !pose) stepPlayback(dt);
