403	    const onPlay = () => start();
404	    wrapRef.current.addEventListener('stage:play', onPlay);
405	    if (document.fonts && document.fonts.ready) document.fonts.ready.then(size);
406	    size(); start();
407	    const el = wrapRef.current;
408	    return () => { cancelAnimationFrame(raf); ro.disconnect(); io.disconnect(); el.removeEventListener('stage:play', onPlay); };
409	  }, []);
410	
411	  // a layer change animates even while paused; the loop stops itself once everything has settled
412	  sEffect(() => {
413	    if (!playing) settle.current(); // never leave a paused replay half-faded
