418	  const seek = (e) => {
419	    loop.current = { phase: 'play', time: 0 };
420	    wrapRef.current.style.setProperty('--fade', '1');
421	    tRef.current = Math.max(0, e.si - 8);
422	    setPlaying(true);
423	    redraw.current();
424	    kick();
425	  };
426	
427	  const s = S.current;
428	  const log = s.events.slice(0, passed).reverse().slice(0, 4);
429	  const layers = [['detect', 'Pose'], ['corners', 'Corners'], ['strike', 'Strikes'], ['log', 'Timeline']];
430	  const on = (k) => mode === 'full' || mode === k;
431	
432	  return (
433	    <div className={'stage-panel mode-' + mode} ref={wrapRef}>
434	      <div className="stage-hud">
435	        <ol className="stage-layers" aria-label="Pipeline layers shown">
436	          {layers.map(([k, l]) => <li key={k} className={on(k) ? 'on' : ''}>{l}</li>)}
437	        </ol>
438	        <div className="stage-frame mono"><span>frame</span> <b ref={frameRef}>{s.start}</b></div>
439	        <button className="stage-play" type="button" onClick={() => { track(playing ? 'replay-pause' : 'replay-play'); setPlaying((p) => !p); }} aria-label={playing ? 'Pause replay' : 'Play replay'}>
