441	        </button>
442	      </div>
443	      <div className="stage-canvas">
444	        <canvas ref={canvasRef} role="img" aria-label="Two fighters drawn as skeletons from real pose data, with red and blue tracking boxes. Each strike flashes the limb that threw it." />
445	        <div className="stage-read mono" ref={readRef} aria-hidden="true"></div>
446	      </div>
447	      <div className="stage-log" aria-hidden={mode === 'full' || mode === 'log' ? undefined : true}>
448	        {log.length === 0 && <div className="log-empty">Strikes appear here as they land.</div>}
449	        {log.map((e) => (
450	          <button type="button" className="log-row" key={e.f} onClick={() => { track('log-seek'); seek(e); }} tabIndex={mode === 'full' || mode === 'log' ? undefined : -1}>
451	            <span className="mono log-f">{e.f}</span>
452	            <span className={'log-c c' + e.c}>{CORNER_NAME[e.c]}</span>
453	            <span className="log-d">{STRIKE_LABEL[e.a] || e.a} to the {e.t}</span>
454	          </button>
455	        ))}
456	      </div>
457	    </div>
458	  );
459	}
460	
461	Object.assign(window, { ExchangeStage });
