          <button type="button" className="log-row" key={e.f} onClick={() => { track('log-seek'); seek(e); }} tabIndex={mode === 'full' || mode === 'log' ? undefined : -1}>
            <span className="mono log-f">{e.f}</span>
            <span className={'log-c c' + e.c}>{CORNER_NAME[e.c]}</span>
