const S = prepExchange(window.EXCHANGE);
const ts = [84, 88, 92, 95, 98, 100, 101, 102];
const cw = 400, ch = 300;
const big = document.createElement('canvas'); big.width = cw * 4; big.height = ch * 2; big.id = 'sheet';
Object.assign(big.style, { position: 'fixed', inset: '0', width: '100vw', height: (100 * 2 * ch / (cw * 4)) + 'vw', zIndex: 9999, background: '#0f1012' });
const g = big.getContext('2d'); g.fillStyle = '#0f1012'; g.fillRect(0, 0, big.width, big.height);
ts.forEach((t, k) => {
  const c = document.createElement('canvas'); c.width = cw; c.height = ch;
  drawStage(c.getContext('2d'), S, cw, ch, { t, mode: 'full', colour: 1, strip: 1, zoom: 1, pose: null }, 1);
  g.drawImage(c, (k % 4) * cw, Math.floor(k / 4) * ch);
  g.fillStyle = '#fff'; g.font = '14px monospace'; g.fillText('t=' + t, (k % 4) * cw + 8, Math.floor(k / 4) * ch + 290);
});
document.getElementById('sheet')?.remove(); document.body.appendChild(big); 'ok'

